 createAtmosphere(){const geo=new THREE.BufferGeometry(),positions=[];for(let i=0;i<700;i++){const a=i*2.399963,y=1-2*(i+.5)/700,r=Math.sqrt(1-y*y);positions.push(Math.cos(a)*r*260,y*260,Math.sin(a)*r*260);}geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));this.scene.add(new THREE.Points(geo,new THREE.PointsMaterial({size:.22,color:'#a5bdc9',transparent:true,opacity:.55})));this.sunOrb=new THREE.Mesh(new THREE.SphereGeometry(3,24,16),new THREE.MeshBasicMaterial({color:'#fff1b7'}));this.scene.add(this.sunOrb);this.halo=new THREE.Mesh(new THREE.SphereGeometry(R+1.1,96,64),new THREE.ShaderMaterial({uniforms:{sun:{value:new THREE.Vector3(0,0,1)}},vertexShader:'varying vec3 n; varying vec3 p;void main(){vec4 w=modelMatrix*vec4(position,1.);n=normalize(mat3(modelMatrix)*normal);p=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}',fragmentShader:'varying vec3 n;varying vec3 p;uniform vec3 sun;void main(){vec3 v=normalize(cameraPosition-p);float rim=pow(1.-abs(dot(normalize(n),v)),3.);float day=max(.08,dot(normalize(n),sun));gl_FragColor=vec4(mix(vec3(.08,.25,.46),vec3(.32,.75,.9),day),rim*.3);}',transparent:true,depthWrite:false,side:THREE.BackSide}));this.scene.add(this.halo);this.dots=new THREE.InstancedMesh(new THREE.SphereGeometry(1,5,3),new THREE.MeshBasicMaterial(),MAX_CREATURES);this.dots.instanceColor=new THREE.InstancedBufferAttribute(new Float32Array(MAX_CREATURES*3),3);this.dots.frustumCulled=false;this.scene.add(this.dots);this.dotOwners=[];}
 bind(){let down=null,pinch=null;const pointers=new Map(),el=this.renderer.domElement;el.style.touchAction='none';el.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});down={x:e.clientX,y:e.clientY,moved:0,pan:e.button!==0||e.shiftKey};el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinch)this.zoom(pinch/Math.max(1,d));pinch=d;if(down)down.moved=100;return;}if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;down.moved+=Math.abs(dx)+Math.abs(dy);if(down.moved>4){this.following=false;const scale=this.distance/(innerHeight*.9)*(down.pan?.7:1);this.focus=move(this.focus.x,this.focus.z,-dx*scale,dy*scale);this.envClock=1;this.onOrbit?.();}down.x=e.clientX;down.y=e.clientY;});el.addEventListener('pointerup',e=>{if(down&&down.moved<6&&e.button===0)this.click(e);pointers.delete(e.pointerId);down=null;pinch=null;});el.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);down=null;pinch=null;});el.addEventListener('wheel',e=>{e.preventDefault();this.zoom(Math.exp(e.deltaY*.001));},{passive:false});el.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('resize',()=>this.resize());}
