 select(id,follow=false){this.selected=id;this.following=follow;if(follow){const c=this.sim.byId.get(id);if(c)this.focus={x:c.x,z:c.z};this.desiredDistance=12;}}
 cameraUpdate(dt){const c=this.sim.byId.get(this.selected);if(c&&this.following){this.focus.x+=wrap(c.x-this.focus.x)*Math.min(1,dt*4);this.focus.z+=(c.z-this.focus.z)*Math.min(1,dt*4);}this.distance+=(this.desiredDistance-this.distance)*Math.min(1,dt*6);const n=normal(this.focus.x,this.focus.z),north=normal(this.focus.x,this.focus.z+Math.PI*R/2),close=1-clamp((this.distance-20)/65,0,1),h=terrain(this.focus.x,this.focus.z);this.target.set(n.x*(R+h)*close,n.y*(R+h)*close,n.z*(R+h)*close);this.camera.position.set(n.x*(R+h+this.distance)+north.x*this.distance*.22*close,n.y*(R+h+this.distance)+north.y*this.distance*.22*close,n.z*(R+h+this.distance)+north.z*this.distance*.22*close);set(this.camera.up,north);this.camera.lookAt(this.target);this.camera.updateMatrixWorld();this.clip.multiplyMatrices(this.camera.projectionMatrix,this.camera.matrixWorldInverse);this.frustum.setFromProjectionMatrix(this.clip);}
