 project(x,y,z){const a=this.projectionAnchor;if(!a)return xyz(x,z,y);const f=this.projectionFrame,dx=wrap(x-a.x),dz=z-a.z,r=R+y;return{x:f.n.x*r+f.e.x*dx+f.t.x*dz,y:f.n.y*r+f.t.y*dz,z:f.n.z*r+f.e.z*dx+f.t.z*dz};}
