 place(mesh,i,x,z,h,sx,sy,sz,paint,heading=0){set(temp.position,xyz(x,z,h));set(pa,normal(x,z));temp.quaternion.setFromUnitVectors(up,pa);temp.rotateY(heading);temp.scale.set(sx,sy,sz);temp.updateMatrix();mesh.setMatrixAt(i,temp.matrix);if(paint){col.set(paint);mesh.setColorAt(i,col);}}
 finish(mesh,n){mesh.count=n;mesh.instanceMatrix.clearUpdateRanges();if(n)mesh.instanceMatrix.addUpdateRange(0,n*16);mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor){mesh.instanceColor.clearUpdateRanges();if(n)mesh.instanceColor.addUpdateRange(0,n*3);mesh.instanceColor.needsUpdate=true;}}
 updateEnvironment(){if(!this.frustum)return;let n=0;for(const f of this.sim.food){const base=terrain(f.x,f.z)+.1;if(!this.visible(f.x,f.z,base+1))continue;const d=this.camera.position.distanceTo(set(pa,xyz(f.x,f.z,base)));if(d>95)continue;const sc=.12+f.growth*.88,plant=PLANTS[f.type],detail=d<30&&this.qualityTier<2,pieces=detail?(f.type===2?7:4):1,wilt=clamp((plant.life-f.age)/25,.25,1),h=f.type===2?.85:f.type===1?.55:f.type===4?.36:.25;for(let k=0;k<pieces&&n<15000;k++){const a=k*2.4+f.seed,p=detail?move(f.x,f.z,Math.cos(a)*.15*sc,Math.sin(a)*.15*sc):f;this.place(this.foodMesh,n++,p.x,p.z,base+(detail?(k+1)/pieces*h:h*.5)*sc,(detail?.13:.3)*sc,(detail?.17:h*.5)*sc*wilt,(detail?.18:.3)*sc,plant.color,a);}}this.finish(this.foodMesh,n);n=0;for(const p of this.sim.soil.slice(-100))if(this.visible(p.x,p.z))this.place(this.remainsMesh,n++,p.x,p.z,terrain(p.x,p.z)+.035,.35,.04,.35);this.finish(this.remainsMesh,n);}
 updateCultureGeometry(){let n=0;for(const b of this.sim.culture.blocks)if(this.visible(b.x,b.z,terrain(b.x,b.z)+b.level*.28))this.place(this.buildMesh,n++,b.x,b.z,terrain(b.x,b.z)+.14+b.level*.28,.74,.28,.74,MATERIALS[b.type].color);this.finish(this.buildMesh,n);n=0;for(const r of this.sim.culture.materials){if(!this.visible(r.x,r.z)||this.camera.position.distanceTo(set(pa,xyz(r.x,r.z)))>85)continue;this.place(this.resourceMesh,n++,r.x,r.z,terrain(r.x,r.z)+.15,.23,.15,.23,MATERIALS[r.type].color,r.id);}this.finish(this.resourceMesh,n);n=0;for(const c of this.sim.creatures)if(c.mind?.carrying&&this.visibleIds.has(c.id)){const p=move(c.x,c.z,Math.sin(c.heading)*.65,Math.cos(c.heading)*.65);this.place(this.carryMesh,n++,p.x,p.z,terrain(c.x,c.z)+1,.85,.85,.85,MATERIALS[c.mind.carrying.type].color,c.heading);}this.finish(this.carryMesh,n);}
 click(e){this.pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);this.raycaster.setFromCamera(this.pointer,this.camera);const ground=this.raycaster.intersectObjects([this.land,this.ocean],false)[0];if(!ground)return;const hit=this.raycaster.intersectObjects([this.cells,this.dots],false).find(h=>h.distance<ground.distance+2),id=hit?(hit.object===this.cells?this.owners[hit.instanceId]:this.dotOwners[hit.instanceId]):null;this.onClick?.({id,...coordinates(ground.point)});}
 setQuality(tier){this.qualityTier=tier;this.renderer.setPixelRatio(Math.min(devicePixelRatio,[1.25,1,.8][tier]));this.renderer.setSize(innerWidth,innerHeight);this.renderer.shadowMap.enabled=false;this.envClock=1;}
 render(dt){if(!this.frustum)return;const started=performance.now();this.elapsed+=dt;this.visualTime=this.visualTime===undefined?this.sim.time:this.visualTime+(this.sim.time-this.visualTime)*Math.min(1,dt*12);this.cameraUpdate(dt);const sun=sunDirection(this.visualTime);this.sun.position.set(sun.x*160,sun.y*160,sun.z*160);this.sunOrb.position.copy(this.sun.position);set(this.halo.material.uniforms.sun.value,sun);this.cellIndex=0;this.boneIndex=0;let dots=0;this.visibleIds.clear();this.lodStats={full:0,simple:0,dots:0,hidden:0};const ordered=this.sim.creatures.map(c=>({c,d:this.camera.position.distanceTo(set(pa,xyz(c.x,c.z,terrain(c.x,c.z)+1)))})).sort((a,b)=>a.d-b.d);for(const {c,d} of ordered){if(!this.visible(c.x,c.z,terrain(c.x,c.z)+1)){this.lodStats.hidden++;continue;}this.visibleIds.add(c.id);const px=innerHeight/(2*Math.tan(this.camera.fov*Math.PI/360)*d)*SPECIES[c.species].size*c.gene,budget=[23000,15000,9500][this.qualityTier];if(px<14||this.cellIndex>budget){this.place(this.dots,dots,c.x,c.z,terrain(c.x,c.z)+.7,.23,.3,.23,SPECIES[c.species].color);this.dotOwners[dots++]=c.id;this.lodStats.dots++;continue;}this.renderLod=px>42&&this.qualityTier===0?0:1;this.renderCreature(c,dt);this.lodStats[this.renderLod?'simple':'full']++;}for(const c of this.sim.remains.slice(-32))if(c.dna&&this.visible(c.x,c.z)&&this.distance<65){this.renderLod=1;this.renderCreature(c,dt,true);}for(const [id,a] of this.actors)if(this.frame-a.lastSeen>4){this.actors.delete(id);this.cellCounts.delete(id);}this.finish(this.cells,this.cellIndex);this.finish(this.boneMesh,this.boneIndex);this.finish(this.dots,dots);this.envClock+=dt;if(this.envClock>.18){this.envClock=0;this.updateEnvironment();this.updateCultureGeometry();}const sel=this.sim.byId.get(this.selected);this.selection.visible=!!sel&&this.visible(sel.x,sel.z);if(sel){set(this.selection.position,xyz(sel.x,sel.z,terrain(sel.x,sel.z)+.08));set(pa,normal(sel.x,sel.z));this.selection.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),pa);this.selection.scale.setScalar(sel.gene);}this.pulseMeshes.forEach((m,i)=>{const p=this.sim.pulses[i];m.visible=!!p&&this.visible(p.x,p.z);if(p){set(m.position,xyz(p.x,p.z,terrain(p.x,p.z)+.12));set(pa,normal(p.x,p.z));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),pa);m.scale.setScalar((1-p.life)*3+.6);m.material.opacity=p.life*.5;}});this.renderer.render(this.scene,this.camera);this.frame++;this.renderMs=performance.now()-started;}
